1	import { db } from "../lib/db";
2	import { SANDBOX } from "../lib/sandbox";
3	import { pve, node as defaultNode, pveFor, getGuestDiskUsage } from "../lib/proxmox";
4	import { effectiveDiskGB } from "../lib/extra-disk";
5	import {
6	  nodeStorageUsage,
7	  nodeRamUsage,
8	  backupSummary,
9	  stuckJobs,
10	  workerHealth,
11	  fmtAge,
12	  DISK_WARN_RATIO,
13	  RAM_WARN_RATIO,
14	  BACKUP_STALE_MS,
15	  QUEUE_BACKLOG_ALERT,
16	  STUCK_JOB_MS,
17	} from "../lib/monitoring";
18	
19	/**
20	 * Monitoring sweep — run periodically from the worker loop. Read-only checks
21	 * that raise dashboard notifications for all ADMINs when a threshold trips.
22	 *
23	 * Notifications are de-duplicated by title within a rolling window so a
24	 * persistent condition (e.g. a node stuck at 90% disk) alerts once every few
25	 * hours rather than every sweep.
26	 */
27	
28	const DEDUPE_HOURS = Number(process.env.NXEON_ALERT_DEDUPE_HOURS ?? 3);
29	
30	/**
31	 * Fan a single alert out to every ADMIN, unless an identically-titled alert
32	 * already went out within the dedupe window.
33	 */
34	export async function notifyAdmins(
35	  title: string,
36	  body: string,
37	  href = "/admin/monitoring"
38	): Promise<void> {
39	  const since = new Date(Date.now() - DEDUPE_HOURS * 60 * 60_000);
40	  const recent = await db.notification.findFirst({
41	    where: { title, createdAt: { gt: since } },
42	    select: { id: true },
43	  });
44	  if (recent) return;
45	
46	  const admins = await db.user.findMany({ where: { role: "ADMIN" }, select: { id: true } });
47	  if (admins.length === 0) return;
48	
49	  await db.notification.createMany({
50	    data: admins.map((a) => ({ userId: a.id, title, body, href })),
51	  });
52	}
53	
54	// Keep in-guest disk samples for ~5 weeks so the 30-day chart window always has
55	// history without letting the table grow unbounded.
56	const DISK_SAMPLE_RETENTION_DAYS = 35;
57	const GB = 1024 ** 3;
58	
59	/**
60	 * Sample real in-guest disk usage for every RUNNING VM via the QEMU guest agent
61	 * and persist a point into ServerDiskSample. Runs on the monitor cadence.
62	 *
63	 * Best-effort throughout: a missing/not-ready guest agent yields null and is
64	 * simply skipped — it never errors the sweep. In SANDBOX getGuestDiskUsage
65	 * returns a synthetic value, so staging still builds a realistic history.
66	 * Also prunes samples older than the retention window each pass.
67	 */
68	export async function sampleServerDisks(): Promise<void> {
69	  // Retention prune first (cheap, and keeps the table bounded even if sampling
70	  // below throws for every server).
71	  try {
72	    const cutoff = new Date(Date.now() - DISK_SAMPLE_RETENTION_DAYS * 24 * 60 * 60_000);
73	    await db.serverDiskSample.deleteMany({ where: { ts: { lt: cutoff } } });
74	  } catch (e) {
75	    console.error("[monitor] disk-sample prune error", e);
76	  }
77	
78	  let servers: Array<{ id: string; vmid: number | null; node: any; extraDiskGB: number; plan: { diskGB: number } }>;
79	  try {
80	    servers = await db.server.findMany({
81	      where: { status: "RUNNING", vmid: { not: null } },
82	      select: {
83	        id: true,
84	        vmid: true,
85	        extraDiskGB: true,
86	        plan: { select: { diskGB: true } },
87	        node: {
88	          select: { pveNode: true, apiUrl: true, tokenId: true, tokenSecret: true },
89	        },
90	      },
91	    });
92	  } catch (e) {
93	    console.error("[monitor] disk-sample: list servers error", e);
94	    return;
95	  }
96	
97	  for (const s of servers) {
98	    if (s.vmid == null) continue;
99	    try {
100	      const client = s.node
101	        ? pveFor({
102	            apiUrl: s.node.apiUrl,
103	            pveNode: s.node.pveNode,
104	            tokenId: s.node.tokenId,
105	            tokenSecret: s.node.tokenSecret,
106	          })
107	        : pve;
108	      const pnode = s.node?.pveNode ?? defaultNode;
109	      const usage = await getGuestDiskUsage(client, pnode, s.vmid, effectiveDiskGB(s.plan.diskGB, s.extraDiskGB) * GB);
110	      if (!usage) continue; // agent not ready — skip, no error
111	      await db.serverDiskSample.create({
112	        data: {
113	          serverId: s.id,
114	          usedBytes: BigInt(Math.max(0, Math.round(usage.usedBytes))),
115	          totalBytes: BigInt(Math.max(0, Math.round(usage.totalBytes))),
116	        },
117	      });
118	    } catch (e) {
119	      console.error(`[monitor] disk-sample error for server ${s.id}`, e);
120	    }
121	  }
122	}
123	
124	export async function monitorSweep(): Promise<void> {
125	  if (SANDBOX) return; // no real nodes/Proxmox to monitor in the sandbox
126	  // 1. Node disk usage > threshold
127	  try {
128	    const storage = await nodeStorageUsage();
129	    for (const s of storage) {
130	      if (s.reachable && s.total > 0 && s.ratio > DISK_WARN_RATIO) {
131	        const pct = Math.round(s.ratio * 100);
132	        await notifyAdmins(
133	          `Disk capacity warning — ${s.node}/${s.storage} at ${pct}%`,
134	          `Storage "${s.storage}" on node ${s.node} is ${pct}% full ` +
135	            `(${(s.avail / 1024 ** 3).toFixed(0)} GB free). Free space or add capacity to keep provisioning healthy.`
136	        );
137	      }
138	    }
139	  } catch (e) {
140	    console.error("[monitor] disk check error", e);
141	  }
142	
143	  // 2. Node RAM pressure > threshold
144	  try {
145	    const ram = await nodeRamUsage();
146	    for (const r of ram) {
147	      if (r.reachable && r.total > 0 && r.ratio > RAM_WARN_RATIO) {
148	        const pct = Math.round(r.ratio * 100);
149	        await notifyAdmins(
150	          `Memory pressure — ${r.node} at ${pct}%`,
151	          `Node ${r.node} RAM is ${pct}% used. New deploys may be refused until usage drops.`
152	        );
153	      }
154	    }
155	  } catch (e) {
156	    console.error("[monitor] ram check error", e);
157	  }
158	
159	  // 3. Stuck jobs (RUNNING beyond the stuck threshold)
160	  try {
161	    const stuck = await stuckJobs();
162	    if (stuck.length > 0) {
163	      const mins = Math.round(STUCK_JOB_MS / 60_000);
164	      const lines = stuck
165	        .slice(0, 8)
166	        .map(
167	          (j) =>
168	            `• ${j.type}${j.hostname ? ` (${j.hostname})` : ""} — running ${fmtAge(
169	              Date.now() - j.updatedAt.getTime()
170	            )}`
171	        )
172	        .join("\n");
173	      await notifyAdmins(
174	        `Stuck jobs — ${stuck.length} running > ${mins}m`,
175	        `The worker has job(s) stuck in RUNNING:\n${lines}`
176	      );
177	    }
178	  } catch (e) {
179	    console.error("[monitor] stuck-job check error", e);
180	  }
181	
182	  // 4. Worker liveness + pending-job backlog
183	  try {
184	    const wh = await workerHealth();
185	    if (wh.status === "down") {
186	      await notifyAdmins(
187	        "Worker appears stopped",
188	        wh.detail + ". Check the provisioning worker process."
189	      );
190	    }
191	    if (wh.queuedBacklog >= QUEUE_BACKLOG_ALERT) {
192	      await notifyAdmins(
193	        `Job backlog building — ${wh.queuedBacklog} queued`,
194	        `${wh.queuedBacklog} jobs are waiting in the queue. The worker may be overloaded or slow.`
195	      );
196	    }
197	  } catch (e) {
198	    console.error("[monitor] worker check error", e);
199	  }
200	
201	  // 5. Backup freshness (best-effort; skipped if backup storage isn't listable)
202	  try {
203	    const bk = await backupSummary();
204	    if (bk.reachable && bk.count > 0 && bk.newestCtime !== null) {
205	      const ageMs = Date.now() - bk.newestCtime * 1000;
206	      if (ageMs > BACKUP_STALE_MS) {
207	        await notifyAdmins(
208	          `Backups look stale — newest is ${fmtAge(ageMs)} old`,
209	          `The most recent backup on disk is ${fmtAge(ageMs)} old. Verify the backup schedule is running.`
210	        );
211	      }
212	    }
213	  } catch (e) {
214	    console.error("[monitor] backup check error", e);
215	  }
216	}
