/**
 * Bandwidth metering — the one place that decides (a) how Proxmox's per-VM
 * network counters become `Server.bwInBytes` / `bwOutBytes`, and (b) how much
 * confidence a usage figure is allowed to project at the customer.
 *
 * Background: both columns shipped with `@default(0)` and NOTHING ever wrote
 * them. Every plan sells a bandwidth allowance, the billing panel was titled
 * "Transfer used this cycle … versus plan allowance", and it read a permanent
 * `0 B / 20 TB · 0%`. Downstream, `worker/abuse.ts` computed its outbound rate
 * from `bwOutBytes` deltas, so `deltaBytes` was always 0 and BANDWIDTH_SPIKE
 * could never fire: the platform shipped an abuse detector that could not
 * detect anything. This module is the missing signal.
 *
 * Two hard rules, both of which exist because a *confidently wrong* number is
 * worse here than a visibly incomplete one:
 *
 *  1. Never invent traffic. Proxmox `netin`/`netout` are cumulative per QEMU
 *     PROCESS, not per VM lifetime — a stop/start, a hard reset, a reinstall or
 *     a live migration replaces the process and the counters restart at 0. A
 *     naive `cur - prev` then goes hugely negative, and (when the fresh boot has
 *     already pushed more than the stale baseline held) it can just as easily go
 *     hugely positive. Either way the delta is fiction, and fiction that feeds
 *     an abuse detector can suspend a paying customer. `creditFromCounters`
 *     detects the restart and credits only bytes it can prove happened inside
 *     the interval.
 *  2. Never present a partial period as authoritative. The meter can only know
 *     traffic from the moment it started sampling. `bwUsageView` reports the
 *     period it actually covers, and refuses to render a percentage at all when
 *     no sample has ever been taken — a "0 B / 20 TB · 0%" that means "we never
 *     looked" is exactly the defect class this codebase keeps repeating.
 *
 * Plain module (no "use server"): imported by the worker sweep
 * (worker/monitor.ts), by worker/abuse.ts and by the customer billing page.
 */

import { getSetting, setSetting } from "./settings";

// ---------------------------------------------------------------------------
// Metering-run markers
// ---------------------------------------------------------------------------
// These live in the `Setting` KV rather than on Server rows because
// prisma/schema.prisma is frozen — and because they are genuinely global: one
// sweep meters every VM at once. They are what lets the UI say "measured since"
// and "last updated" instead of implying the number is complete.

/** First sweep that successfully sampled at least one VM. Null = never metered. */
export const BW_STARTED_AT_KEY = "bw_meter_started_at";
/** Start time of the most recent sweep that sampled at least one VM. */
export const BW_LAST_AT_KEY = "bw_meter_last_at";
/** Last time the meter was down longer than it can back-fill (traffic was lost). */
export const BW_GAP_AT_KEY = "bw_meter_gap_at";
/**
 * Last time the meter back-filled a restart gap from RRD. Back-filled bytes land
 * in one write but describe up to an hour of traffic, so any rate computed over
 * that window is inflated. worker/abuse.ts reads this and sits out the affected
 * window rather than raising a spike alert on an accounting artefact.
 */
export const BW_BACKFILL_AT_KEY = "bw_meter_backfill_at";

/**
 * Length of a metering period. Plans sell "N TB / month", so the counters roll
 * on a 30-day cadence: without a roll the totals grow forever and every server
 * eventually renders a bogus "over allowance — overage may apply" warning.
 * This is a metering period, NOT the invoice cycle (renewal dates vary per
 * server and per term length) — which is why the UI names the actual start date
 * instead of the words "this cycle".
 */
export const BW_PERIOD_DAYS = 30;
export const BW_PERIOD_MS = BW_PERIOD_DAYS * 24 * 60 * 60_000;

/**
 * A sample older than this means the meter is not currently reporting. Generous
 * on purpose: sweeps run inline in the worker's strictly serial loop, so a long
 * backup or restore can legitimately delay one by tens of minutes. Crossing it
 * only changes the wording shown to the customer ("last updated Xh ago"), never
 * the number.
 */
export const BW_STALE_MS = 60 * 60_000;

/**
 * Absurdity ceiling for a credited delta, in bytes/sec (~20 Gbit/s — well above
 * anything this hardware can actually push). Anything faster is a counter
 * artefact (process replaced, PVE restarted, vmid reused), not traffic. Set high
 * so real abuse is never filtered out: a 200 Mbit/s spammer is 100x under it.
 */
export const BW_MAX_PLAUSIBLE_BYTES_PER_SEC = 2_500_000_000;

/**
 * Tolerance when comparing guest uptime against the sample interval. Proxmox
 * reports whole seconds and the interval is measured on our clock, so a couple
 * of seconds of skew is normal; 90s keeps a slow sweep from being mistaken for
 * a VM restart.
 */
export const BW_UPTIME_SLACK_SEC = 90;

// ---------------------------------------------------------------------------
// Counter sampling
// ---------------------------------------------------------------------------

/** The fields we read from `GET /nodes/<node>/qemu/<vmid>/status/current`. */
export type BwCounters = {
  /** Cumulative inbound bytes for the current QEMU process. */
  netin: number;
  /** Cumulative outbound bytes for the current QEMU process. */
  netout: number;
  /** Guest uptime in seconds (0 when not running). */
  uptimeSec: number;
  /** QEMU pid — changes iff the process was replaced, i.e. the counters reset. */
  pid: number | null;
};

export type BwSample = BwCounters & { atMs: number };

export type BwCreditReason =
  | "delta" // clean monotonic delta, fully inside the interval
  | "vm-restarted" // counters reset mid-interval; credited only post-restart bytes
  | "counter-rollback" // counters moved backwards with no restart to explain it
  | "implausible"; // delta faster than any real link — counter artefact

export type BwCredit = {
  inBytes: number;
  outBytes: number;
  reason: BwCreditReason;
};

/**
 * Bytes to add to a server's cumulative totals, given the previous sample and
 * the current one. Pure and total — never throws, never returns a negative.
 *
 * The whole point of this function is the reset case. A VM stop/start, hard
 * reset, reinstall or live migration gives the guest a new QEMU process whose
 * `netin`/`netout` start again at 0 (a soft reboot inside the guest does NOT —
 * the process survives and the counters keep climbing, which is why `pid` and
 * `uptime`, not "did the guest reboot", are the signals used here):
 *
 *   - `pid` changed, or uptime went backwards, or uptime is shorter than the
 *     interval → the reset happened INSIDE this interval, so every byte on the
 *     new counter was transferred during the interval. Credit the raw counter.
 *     Traffic from before the reset is lost; that under-counts, which is the
 *     safe direction. Crediting `cur - prev` here would have been the "hugely
 *     positive" fiction.
 *   - counters moved backwards but uptime/pid say the process was NOT replaced →
 *     our baseline does not describe this VM (vmid reuse, a PVE-side counter
 *     reset). Credit nothing and re-baseline; guessing would fabricate traffic.
 *   - delta implies a rate no link can carry → counter artefact. Credit nothing.
 */
export function creditFromCounters(prev: BwSample, cur: BwSample): BwCredit {
  const intervalSec = Math.max(0, (cur.atMs - prev.atMs) / 1000);
  const zero = { inBytes: 0, outBytes: 0 };

  const sane = (v: number) => (Number.isFinite(v) && v >= 0 ? v : 0);
  const curIn = sane(cur.netin);
  const curOut = sane(cur.netout);
  const prevIn = sane(prev.netin);
  const prevOut = sane(prev.netout);

  const pidChanged =
    prev.pid != null && cur.pid != null && prev.pid !== cur.pid;
  const uptimeWentBack = cur.uptimeSec > 0 && cur.uptimeSec < prev.uptimeSec;
  // Uptime shorter than the gap we are accounting for → it booted inside it.
  const bootedInsideInterval =
    cur.uptimeSec > 0 && cur.uptimeSec + BW_UPTIME_SLACK_SEC < intervalSec;
  const restarted = pidChanged || uptimeWentBack || bootedInsideInterval;
  const wentBackwards = curIn < prevIn || curOut < prevOut;

  // Physical ceiling for this interval. Applied to every branch: a credit is
  // only ever allowed to shrink here, never grow.
  const ceiling =
    intervalSec > 0 ? intervalSec * BW_MAX_PLAUSIBLE_BYTES_PER_SEC : 0;

  if (restarted) {
    // Everything on the fresh counter happened inside this interval.
    if (ceiling > 0 && (curIn > ceiling || curOut > ceiling)) {
      return { ...zero, reason: "implausible" };
    }
    return { inBytes: curIn, outBytes: curOut, reason: "vm-restarted" };
  }

  if (wentBackwards) {
    return { ...zero, reason: "counter-rollback" };
  }

  const inBytes = curIn - prevIn;
  const outBytes = curOut - prevOut;
  if (ceiling > 0 && (inBytes > ceiling || outBytes > ceiling)) {
    return { ...zero, reason: "implausible" };
  }
  return { inBytes, outBytes, reason: "delta" };
}

/**
 * Integrate a Proxmox RRD series into bytes over `(fromSec, toSec]`.
 *
 * Used only to back-fill the gap left by a worker restart: the counter baseline
 * lives in worker memory, so without this every restart silently drops up to a
 * full sweep interval of traffic for every server — on a platform that redeploys
 * several times a day that is a systematic multi-percent under-count of a figure
 * customers are held to.
 *
 * `netin`/`netout` in rrddata are AVERAGE BYTES PER SECOND for each bucket, so
 * bytes = rate x bucket length. Only buckets that closed inside the window are
 * counted: the newest bucket is still filling, and counting it would double-count
 * against the counter delta the next sweep takes. Returns null when no bucket
 * qualified, so callers can tell "no data" from "genuinely zero".
 */
export function integrateRrdBytes(
  rows: Array<Record<string, unknown>>,
  fromSec: number,
  toSec: number
): { inBytes: number; outBytes: number; buckets: number } | null {
  if (!Array.isArray(rows) || rows.length === 0) return null;
  const times = rows.map((r) => Number(r?.time));
  let inBytes = 0;
  let outBytes = 0;
  let buckets = 0;

  for (let i = 0; i < rows.length; i++) {
    const t = times[i];
    if (!Number.isFinite(t)) continue;
    const next = times[i + 1];
    // Bucket length from the series itself; the API's step can change with the
    // timeframe, so never hard-code 60s.
    const step = Number.isFinite(next) && next > t ? next - t : 60;
    if (step <= 0 || step > 3600) continue;
    if (t < fromSec) continue; // before the gap we are filling
    if (t + step > toSec) continue; // still filling, or past the gap

    const ri = Number(rows[i]?.netin);
    const ro = Number(rows[i]?.netout);
    // RRD emits null/undefined for steps it has no data for (including the step
    // a counter reset landed in). Skipping them under-counts; inventing a value
    // would not.
    if (Number.isFinite(ri) && ri >= 0) inBytes += ri * step;
    if (Number.isFinite(ro) && ro >= 0) outBytes += ro * step;
    buckets++;
  }

  if (buckets === 0) return null;
  return { inBytes, outBytes, buckets };
}

// ---------------------------------------------------------------------------
// Meter health (read by the worker and by the customer UI)
// ---------------------------------------------------------------------------

export type BwMeterHealth = {
  /** When metering first ran. Null = never — show no usage figure at all. */
  startedAt: Date | null;
  /** Start of the most recent sweep. */
  lastAt: Date | null;
  /** Last unrecoverable metering outage (traffic in that gap is uncounted). */
  gapAt: Date | null;
  /** Last RRD back-fill — rates spanning it are inflated, see the key's doc. */
  backfillAt: Date | null;
  /** A sample landed within BW_STALE_MS. */
  live: boolean;
  /** Age of `lastAt`, or null if never metered. */
  ageMs: number | null;
};

function parseDate(raw: string): Date | null {
  if (!raw) return null;
  const d = new Date(raw);
  return Number.isNaN(d.getTime()) ? null : d;
}

/** Read the metering markers. One query per key; all four are tiny strings. */
export async function readBwMeterHealth(now = Date.now()): Promise<BwMeterHealth> {
  const [started, last, gap, backfill] = await Promise.all([
    getSetting(BW_STARTED_AT_KEY, ""),
    getSetting(BW_LAST_AT_KEY, ""),
    getSetting(BW_GAP_AT_KEY, ""),
    getSetting(BW_BACKFILL_AT_KEY, ""),
  ]);
  const startedAt = parseDate(started);
  const lastAt = parseDate(last);
  const ageMs = lastAt ? Math.max(0, now - lastAt.getTime()) : null;
  return {
    startedAt,
    lastAt,
    gapAt: parseDate(gap),
    backfillAt: parseDate(backfill),
    live: ageMs !== null && ageMs <= BW_STALE_MS,
    ageMs,
  };
}

/**
 * Record that a sweep ran. `startedAt` is written once, on the first sweep that
 * actually sampled something — it is the honest lower bound on "we have been
 * measuring since", because traffic before the first baseline was never seen.
 */
export async function recordBwSweep(opts: {
  sweepStartMs: number;
  sampled: number;
  gapDetected: boolean;
  backfilled: boolean;
  hadStartedAt: boolean;
}): Promise<void> {
  if (opts.sampled === 0) return; // nothing measured — don't claim a live meter
  const at = new Date(opts.sweepStartMs).toISOString();
  if (!opts.hadStartedAt) await setSetting(BW_STARTED_AT_KEY, at);
  await setSetting(BW_LAST_AT_KEY, at);
  if (opts.gapDetected) await setSetting(BW_GAP_AT_KEY, at);
  if (opts.backfilled) await setSetting(BW_BACKFILL_AT_KEY, at);
}

// ---------------------------------------------------------------------------
// Customer-facing view
// ---------------------------------------------------------------------------

/** Just enough of a Server row to describe its metered usage. */
export type BwServerRow = {
  status: string;
  bwInBytes: bigint | number;
  bwOutBytes: bigint | number;
  bwWindowStart: Date;
};

export type BwUsageView = {
  /**
   * False = we have never metered this server, so there is no figure to show.
   * Callers MUST render an explicit "not measured yet" state rather than the
   * zero — that zero is what made the panel read "0 B / 20 TB · 0%" forever.
   */
  measured: boolean;
  usedBytes: number;
  allowanceBytes: number;
  /** Percent of allowance, or null when `measured` is false. */
  pct: number | null;
  /** Start of the span these bytes actually cover. */
  measuredFrom: Date | null;
  coveredMs: number;
  /** Covered span is shorter than a full period — the total WILL grow. */
  partial: boolean;
  /** Fraction of a full period covered (0..1). */
  coverage: number;
  /** The meter was down long enough inside this window to have lost traffic. */
  hasGap: boolean;
  /** Nothing accrues right now (VM not running / metering stale). */
  accruing: boolean;
};

/**
 * Turn a Server row plus meter health into something honest to render.
 *
 * `measuredFrom` is `max(bwWindowStart, meter startedAt)`: rows that existed
 * before metering did have `bwWindowStart` defaulted to their creation date, and
 * presenting their counters as covering that whole span would claim months of
 * measurement we never performed.
 */
export function bwUsageView(
  server: BwServerRow,
  allowanceBytes: number,
  health: BwMeterHealth,
  now = new Date()
): BwUsageView {
  const usedBytes = Number(server.bwInBytes) + Number(server.bwOutBytes);
  const measured = health.startedAt !== null;

  const windowStart = server.bwWindowStart;
  const measuredFrom = !measured
    ? null
    : windowStart.getTime() > health.startedAt!.getTime()
      ? windowStart
      : health.startedAt!;

  const coveredMs = measuredFrom
    ? Math.max(0, now.getTime() - measuredFrom.getTime())
    : 0;
  const coverage = Math.min(1, coveredMs / BW_PERIOD_MS);

  return {
    measured,
    usedBytes: measured ? usedBytes : 0,
    allowanceBytes,
    pct:
      measured && allowanceBytes > 0 ? (usedBytes / allowanceBytes) * 100 : null,
    measuredFrom,
    coveredMs,
    // 99% counts as complete: the roll happens on the next sweep after the
    // period ends, so demanding an exact 30 days would flag every full period
    // as partial for the few minutes before it rolls.
    partial: coverage < 0.99,
    coverage,
    hasGap:
      measured &&
      health.gapAt !== null &&
      measuredFrom !== null &&
      health.gapAt.getTime() >= measuredFrom.getTime(),
    accruing: server.status === "RUNNING" && health.live,
  };
}

/** "Jul 26, 2026" — the period start, stated instead of implied. */
export function fmtBwDate(d: Date): string {
  return d.toLocaleDateString("en-US", {
    month: "short",
    day: "numeric",
    year: "numeric",
  });
}

/** Compact span for "measured since X (2d 4h of 30 days)". */
export function fmtBwSpan(ms: number): string {
  const m = Math.floor(Math.max(0, ms) / 60_000);
  if (m < 60) return `${m}m`;
  const h = Math.floor(m / 60);
  if (h < 48) return `${h}h`;
  const d = Math.floor(h / 24);
  return `${d}d ${h % 24}h`;
}

