model AuditLog {
  id        String   @id @default(cuid())
  userId    String?
  user      User?    @relation(fields: [userId], references: [id])
  action    String
  detail    String?
  createdAt DateTime @default(now())
}

model Setting {
  key   String @id

import { db } from "@/lib/db";
import { requireArea } from "@/lib/rbac";
import { StatusBadge } from "@/components/StatusBadge";
import { AbuseActions } from "@/components/admin/AbuseActions";

export const dynamic = "force-dynamic";

const sevBadge: Record<string, string> = { HIGH: "ERROR", MEDIUM: "PENDING", LOW: "RUNNING" };

export default async function AdminAbuse() {
  await requireArea("fleet");
  const alerts = await db.abuseAlert.findMany({ orderBy: { createdAt: "desc" }, take: 200 });

  // AbuseAlert stores plain serverId/userId (no relation) — resolve labels in bulk.
  const serverIds = [...new Set(alerts.map((a) => a.serverId))];
  const userIds = [...new Set(alerts.map((a) => a.userId))];
  const [servers, users] = await Promise.all([
    db.server.findMany({ where: { id: { in: serverIds } }, select: { id: true, hostname: true, status: true } }),
    db.user.findMany({ where: { id: { in: userIds } }, select: { id: true, email: true } }),
  ]);
  const serverMap = new Map(servers.map((s) => [s.id, s]));
  const userMap = new Map(users.map((u) => [u.id, u.email]));

  const open = alerts.filter((a) => a.status === "OPEN").length;

  return (
    <div>
      <h1 className="mb-2 text-2xl font-bold">Abuse queue</h1>
      <p className="mb-6 text-sm text-slate-400">
        Outbound-abuse alerts (bandwidth spikes / spam / scanning) raised automatically to protect IP
        reputation. {open} open. Thresholds: <code className="kbd">abuse_outbound_mbps</code>,{" "}
        <code className="kbd">abuse_autosuspend</code> in Settings.
      </p>
      {alerts.length === 0 ? (
        <div className="card text-sm text-slate-400">No abuse alerts. All quiet. 🟢</div>
      ) : (
        <div className="card overflow-x-auto p-0">
          <table className="w-full text-sm">
            <thead className="text-left text-slate-400">
              <tr>
                <th className="px-4 py-3">Server</th>
                <th className="px-4 py-3">Owner</th>
                <th className="px-4 py-3">Kind</th>
                <th className="px-4 py-3">Severity</th>
                <th className="px-4 py-3">Detail</th>
                <th className="px-4 py-3">Status</th>
                <th className="px-4 py-3">When</th>
                <th className="px-4 py-3">Actions</th>
              </tr>
            </thead>
            <tbody>
              {alerts.map((a) => {
                const srv = serverMap.get(a.serverId);
                return (
                  <tr key={a.id} className="border-t border-slate-800">
                    <td className="px-4 py-3 font-medium">{srv?.hostname ?? "—"}</td>
                    <td className="px-4 py-3 text-slate-400">{userMap.get(a.userId) ?? "—"}</td>
                    <td className="px-4 py-3">{a.kind.toLowerCase().replace(/_/g, " ")}</td>
                    <td className="px-4 py-3"><StatusBadge status={sevBadge[a.severity] ?? a.severity} /></td>
                    <td className="max-w-md px-4 py-3 text-xs text-slate-300">{a.detail}</td>
                    <td className="px-4 py-3">{a.status.toLowerCase()}</td>
                    <td className="px-4 py-3 text-slate-400">{a.createdAt.toISOString().replace("T", " ").slice(0, 19)}</td>
                    <td className="px-4 py-3"><AbuseActions id={a.id} status={a.status} /></td>
                  </tr>
                );
              })}
            </tbody>
          </table>
        </div>
      )}
    </div>
  );
}

