import { db } from "../lib/db";
import { SANDBOX } from "../lib/sandbox";
import { getSettingInt, getSettingBool } from "../lib/settings";
import { BW_MAX_PLAUSIBLE_BYTES_PER_SEC, readBwMeterHealth } from "../lib/bandwidth";
import { notifyAdmins } from "./monitor";

/**
 * Outbound-abuse detection. Compares each running server's cumulative outbound
 * byte counter (`Server.bwOutBytes`, written by the metering sweep in
 * worker/monitor.ts) against the previous sample to derive a sustained outbound
 * rate. A rate over the configurable threshold — a compromised VM sending spam,
 * DDoS egress, port scanning — raises an AbuseAlert and notifies admins.
 * Protects the platform's (and the mail IPs') reputation.
 *
 * This code existed before the metering sweep did, so `bwOutBytes` was always 0,
 * `deltaBytes` was always 0, and BANDWIDTH_SPIKE could never fire: the platform
 * shipped an abuse subsystem that could not detect anything. Now that it has a
 * real signal, the risk inverts — a false positive takes a paying customer's
 * server off the network. Everything below is therefore biased towards being
 * slow rather than wrong:
 *
 *   - The meter must be LIVE. Stale counters produce meaningless rates.
 *   - The window must be at least ABUSE_MIN_WINDOW_SEC, so what trips the alert
 *     is a sustained transfer and not a legitimate burst (a customer restoring a
 *     backup out of their VM can saturate a link for a minute).
 *   - A window the meter back-filled from RRD is skipped: back-filled bytes land
 *     in a single write but describe up to an hour of traffic, so the rate over
 *     that window is inflated by an accounting artefact, not by the customer.
 *   - A delta faster than any real link is discarded as a counter artefact.
 *   - AUTOMATIC SUSPENSION IS OFF BY DEFAULT and, even when enabled, needs the
 *     breach to repeat across consecutive windows. Alerting is the default
 *     response; a human decides.
 *
 * Settings: `abuse_outbound_mbps` (default 200), `abuse_autosuspend` (default
 * false — leave it false unless you have operators watching the queue).
 */

/**
 * Minimum measurement window. The sweep runs ~every 10 min, so this is normally
 * satisfied comfortably; it only bites right after a worker restart, when the
 * first window can be short. A 60-second window at 200 Mbit/s is an ordinary
 * backup upload, not abuse.
 */
const ABUSE_MIN_WINDOW_SEC = 300;

/**
 * Absolute egress floor for the window. Guards against an operator setting
 * `abuse_outbound_mbps` very low and turning ordinary traffic into alerts.
 */
const ABUSE_MIN_BYTES = 1_000_000_000; // 1 GB

/** Consecutive breaching windows required before auto-suspend is even considered. */
const AUTOSUSPEND_MIN_BREACHES = 2;
/** …and the breaches must span at least this long in total. */
const AUTOSUSPEND_MIN_SUSTAIN_MS = 10 * 60_000;
/**
 * …and be contiguous: two breaches days apart are two incidents for a human to
 * read, not one sustained attack to act on automatically.
 */
const AUTOSUSPEND_MAX_BREACH_GAP_MS = 60 * 60_000;

type SpikeMetric = {
  mbps: number;
  windowSec: number;
  bytes: number;
  breaches: number;
  firstBreachAt: string;
  lastBreachAt: string;
};

function readMetric(raw: unknown): SpikeMetric | null {
  if (!raw || typeof raw !== "object") return null;
  const m = raw as Record<string, unknown>;
  const breaches = Number(m.breaches);
  if (!Number.isFinite(breaches)) return null;
  return {
    mbps: Number(m.mbps) || 0,
    windowSec: Number(m.windowSec) || 0,
    bytes: Number(m.bytes) || 0,
    breaches,
    firstBreachAt: typeof m.firstBreachAt === "string" ? m.firstBreachAt : "",
    lastBreachAt: typeof m.lastBreachAt === "string" ? m.lastBreachAt : "",
  };
}

export async function abuseSweep(): Promise<void> {
  if (SANDBOX) return; // no real traffic to measure in the sandbox

  // Without a live meter every delta below is either zero or stale, and a rate
  // computed from a stale counter is exactly the kind of number that suspends
  // the wrong customer. Sit out entirely rather than guess.
  const meter = await readBwMeterHealth();
  if (!meter.live) {
    if (meter.startedAt === null) {
      console.warn("[abuse] bandwidth metering has never run — outbound detection inactive");
    } else {
      console.warn(
        `[abuse] bandwidth metering is stale (last sample ${Math.round((meter.ageMs ?? 0) / 60_000)}m ago)` +
          " — skipping outbound detection this sweep"
      );
    }
    return;
  }

  const thresholdMbps = await getSettingInt("abuse_outbound_mbps", 200);
  const autoSuspend = await getSettingBool("abuse_autosuspend", false);
  const now = new Date();

  const servers = await db.server.findMany({
    where: { status: "RUNNING" },
    select: {
      id: true,
      userId: true,
      hostname: true,
      bwOutBytes: true,
      abuseBwMark: true,
      abuseBwMarkAt: true,
    },
  });

  for (const s of servers) {
    const mark = s.abuseBwMark;
    const markAt = s.abuseBwMarkAt;
    // Re-mark for the next window regardless of outcome.
    await db.server.update({
      where: { id: s.id },
      data: { abuseBwMark: s.bwOutBytes, abuseBwMarkAt: now },
    });

    if (mark == null || markAt == null) continue;
    const deltaBytes = Number(s.bwOutBytes - mark);
    const windowSec = (now.getTime() - markAt.getTime()) / 1000;

    // Non-positive delta: either genuinely idle, or the metering period rolled
    // and reset the counter below the mark. Nothing to measure either way.
    if (deltaBytes <= 0) continue;
    // Too short to call anything "sustained".
    if (windowSec < ABUSE_MIN_WINDOW_SEC) continue;
    if (deltaBytes < ABUSE_MIN_BYTES) continue;
    // The meter back-filled inside this window, so these bytes cover more time
    // than the window does and the rate is inflated. Skip; the next clean window
    // will still catch a real abuser.
    if (meter.backfillAt && meter.backfillAt.getTime() >= markAt.getTime()) continue;
    // A delta faster than any physical link is a counter artefact. Never let one
    // suspend a customer.
    if (deltaBytes / windowSec > BW_MAX_PLAUSIBLE_BYTES_PER_SEC) {
      console.warn(
        `[abuse] discarding implausible outbound delta for ${s.hostname}: ` +
          `${deltaBytes} bytes over ${Math.round(windowSec)}s`
      );
      continue;
    }

    const mbps = (deltaBytes * 8) / windowSec / 1_000_000;
    if (mbps < thresholdMbps) continue;

    const severity = mbps >= thresholdMbps * 3 ? "HIGH" : "MEDIUM";
    const detailNow =
      `Sustained ~${mbps.toFixed(0)} Mbps outbound on ${s.hostname} over ` +
      `${Math.round(windowSec)}s (threshold ${thresholdMbps} Mbps, ` +
      `${(deltaBytes / 1e9).toFixed(1)} GB egress).`;

    // One open alert per server+kind; don't spam the queue every sweep. The open
    // alert doubles as the breach counter that gates auto-suspend.
    const existing = await db.abuseAlert.findFirst({
      where: { serverId: s.id, kind: "BANDWIDTH_SPIKE", status: "OPEN" },
    });

    let breaches = 1;
    let firstBreachAt = now;
    let lastBreachAt: Date | null = null;

    if (existing) {
      const prev = readMetric(existing.metric);
      breaches = (prev?.breaches ?? 1) + 1;
      const prevFirst = prev?.firstBreachAt ? new Date(prev.firstBreachAt) : existing.createdAt;
      firstBreachAt = Number.isNaN(prevFirst.getTime()) ? existing.createdAt : prevFirst;
      const prevLast = prev?.lastBreachAt ? new Date(prev.lastBreachAt) : existing.createdAt;
      lastBreachAt = Number.isNaN(prevLast.getTime()) ? existing.createdAt : prevLast;

      await db.abuseAlert.update({
        where: { id: existing.id },
        data: {
          // Escalate severity but never quietly de-escalate an alert a human may
          // already be reading.
          severity: severity === "HIGH" ? "HIGH" : existing.severity,
          detail: `${detailNow} Breach ${breaches} of an ongoing spike (first seen ${firstBreachAt.toISOString()}).`,
          metric: {
            mbps: Math.round(mbps),
            windowSec: Math.round(windowSec),
            bytes: deltaBytes,
            breaches,
            firstBreachAt: firstBreachAt.toISOString(),
            lastBreachAt: now.toISOString(),
          } satisfies SpikeMetric,
        },
      });
    } else {
      await db.abuseAlert.create({
        data: {
          serverId: s.id,
          userId: s.userId,
          kind: "BANDWIDTH_SPIKE",
          severity,
          detail: detailNow,
          metric: {
            mbps: Math.round(mbps),
            windowSec: Math.round(windowSec),
            bytes: deltaBytes,
            breaches: 1,
            firstBreachAt: now.toISOString(),
            lastBreachAt: now.toISOString(),
          } satisfies SpikeMetric,
        },
      });
    }

    // notifyAdmins de-duplicates by title within a rolling window, so a spike
    // that persists for hours notifies once rather than every sweep.
    await notifyAdmins(
      `Abuse alert: outbound spike on ${s.hostname}`,
      `${s.hostname} is pushing ~${mbps.toFixed(0)} Mbps outbound over ${Math.round(windowSec)}s ` +
        `(threshold ${thresholdMbps} Mbps). Possible spam, DDoS egress, or port scanning. ` +
        `The server is still online — review and act in the admin abuse queue.`,
      "/admin/abuse"
    );

    // ---- Automatic suspension: opt-in, and never on first detection ----------
    //
    // `abuse_autosuspend` defaults to false and should stay false unless someone
    // is watching the queue. Taking a paying customer offline by mistake is far
    // worse than reacting to abuse a sweep later, and legitimate traffic reaches
    // these rates: a big backup restored out of a VM, a launch-day game server,
    // a video site. Gates, all required:
    //   1. the operator explicitly enabled it,
    //   2. this window is >= 3x the threshold (HIGH),
    //   3. the breach repeated across consecutive windows and has lasted long
    //      enough to be an ongoing transfer rather than one spike,
    //   4. no job is already in flight for this server.
    if (!autoSuspend || severity !== "HIGH") continue;
    if (breaches < AUTOSUSPEND_MIN_BREACHES) continue;
    if (now.getTime() - firstBreachAt.getTime() < AUTOSUSPEND_MIN_SUSTAIN_MS) continue;
    if (
      lastBreachAt !== null &&
      now.getTime() - lastBreachAt.getTime() > AUTOSUSPEND_MAX_BREACH_GAP_MS
    ) {
      continue; // not contiguous — separate incidents, leave them to a human
    }

    const pending = await db.job.count({
      where: { serverId: s.id, status: { in: ["QUEUED", "RUNNING"] } },
    });
    if (pending > 0) continue;

    // Record WHY before enqueuing, exactly as lib/actions-abuse.ts does. This is
    // load-bearing, not a label: `terminateOverdue` deletes only servers whose
    // suspendReason is UNPAID (an abuse suspension tagged wrongly would have its
    // VM and data destroyed as a non-payer, having never been billed or warned,
    // because the renewal sweep skips suspended servers), and `renewNow`
    // auto-unsuspends only UNPAID ones (mis-tagged, a spammer could pay and put
    // themselves straight back on the network).
    await db.server.update({
      where: { id: s.id },
      data: {
        suspendReason: "ABUSE",
        suspendedNote: "suspended pending an abuse review — contact support",
      },
    });
    await db.job.create({ data: { type: "SUSPEND", serverId: s.id } });
    await db.abuseAlert.updateMany({
      where: { serverId: s.id, kind: "BANDWIDTH_SPIKE", status: "OPEN" },
      data: { status: "ACTIONED" },
    });
    // userId is nullable: this suspension had no human actor, and that is
    // precisely what an operator reviewing the log needs to see.
    await db.auditLog.create({
      data: {
        action: "abuse.autosuspend",
        detail:
          `${s.hostname} auto-suspended after ${breaches} consecutive outbound-spike windows ` +
          `(~${mbps.toFixed(0)} Mbps, threshold ${thresholdMbps} Mbps, abuse_autosuspend=true).`,
      },
    });
    await notifyAdmins(
      `Auto-suspended ${s.hostname} for outbound abuse`,
      `${s.hostname} exceeded 3x the outbound threshold across ${breaches} consecutive windows ` +
        `and was auto-suspended because abuse_autosuspend is enabled. It is tagged ` +
        `suspendReason=ABUSE, so billing will not delete it and the customer cannot lift the ` +
        `suspension by paying. Unsuspend from the server page once reviewed.`,
      "/admin/abuse"
    );
  }
}

