const bandwidth = bwServers.map((s) => {
  const usedBytes = Number(s.bwInBytes) + Number(s.bwOutBytes);
  const allowanceBytes = s.plan.bandwidthTB * 1e12;
  const pct = allowanceBytes > 0 ? (usedBytes / allowanceBytes) * 100 : 0;
  return { server: s, usedBytes, allowanceBytes, pct };
});
const totalUsedBytes = bandwidth.reduce((sum, b) => sum + b.usedBytes, 0);
const totalAllowanceBytes = bandwidth.reduce((sum, b) => sum + b.allowanceBytes, 0);
const totalPct = totalAllowanceBytes > 0 ? (totalUsedBytes / totalAllowanceBytes) * 100 : 0;
const meterColor = (pct: number) => (pct > 100 ? "#ef4444" : pct > 80 ? "#f59e0b" : "#6f47f5");
const pctTone = (pct: number) =>
