// Bandwidth usage: metered transfer (bwIn + bwOut, written by the worker's
// metering sweep) vs plan allowance (bandwidthTB * 1e12 bytes).
//
// This panel used to divide the raw columns by the allowance and print the
// result. Nothing wrote those columns, so it read a permanent "0 B / 20 TB ·
// 0%" under the title "Transfer used this cycle" — a figure that looked
// authoritative and was pure fiction. Everything shown now goes through
// bwUsageView, which reports the period the meter ACTUALLY covers and
// withholds the percentage entirely until a sample exists.
const bwHealth = await readBwMeterHealth();
const bandwidth = bwServers.map((s) => ({
  server: s,
  view: bwUsageView(s, s.plan.bandwidthTB * 1e12, bwHealth),
}));
const bwMeasured = bwHealth.startedAt !== null;
const totalUsedBytes = bandwidth.reduce((sum, b) => sum + b.view.usedBytes, 0);
const totalAllowanceBytes = bandwidth.reduce((sum, b) => sum + b.view.allowanceBytes, 0);
const totalPct = totalAllowanceBytes > 0 ? (totalUsedBytes / totalAllowanceBytes) * 100 : 0;
const bwPartial = bandwidth.some((b) => b.view.partial);
const bwGap = bandwidth.some((b) => b.view.hasGap);
const meterColor = (pct: number) => (pct > 100 ? "#ef4444" : pct > 80 ? "#f59e0b" : "#6f47f5");
const pctTone = (pct: number) =>
  pct > 100 ? "text-red-400" : pct > 80 ? "text-amber-400" : "text-slate-400";

import { SANDBOX } from "@/lib/sandbox";
import {
  BW_PERIOD_DAYS,
  bwUsageView,
  fmtBwDate,
  fmtBwSpan,
  readBwMeterHealth,
} from "@/lib/bandwidth";

{/* Bandwidth usage */}
<div className="card">
  <div className="mb-4 flex flex-wrap items-end justify-between gap-3">
    <div>
      <p className="section-label">Bandwidth usage</p>
      <p className="mt-1 text-sm text-slate-400">
        Measured transfer per server versus the plan&apos;s {BW_PERIOD_DAYS}-day allowance.
      </p>
    </div>
    <div className="text-right">
      {bwMeasured ? (
        <>
          <p className={`text-lg font-bold ${pctTone(totalPct)}`}>
            {fmtBytes(totalUsedBytes)}
            <span className="text-sm font-normal text-slate-500">
              {" "}
              / {totalAllowanceBytes > 0 ? fmtBytes(totalAllowanceBytes) : "—"}
            </span>
          </p>
          <p className="text-xs text-slate-500">
            {totalPct.toFixed(0)}% of total allowance{bwPartial ? " so far" : ""}
          </p>
        </>
      ) : (
        <>
          <p className="text-lg font-bold text-slate-500">
            —
            <span className="text-sm font-normal text-slate-500">
              {" "}
              / {totalAllowanceBytes > 0 ? fmtBytes(totalAllowanceBytes) : "—"}
            </span>
          </p>
          <p className="text-xs text-slate-500">not measured yet</p>
        </>
      )}
    </div>
  </div>

  {/* Say what the number is worth BEFORE showing it. A partial period read
      as a full month is the same defect as a figure that was never
      measured at all: both look authoritative and neither is. */}
  {!bwMeasured ? (
    <div className="mb-4 rounded-lg border border-white/[0.06] bg-white/[0.02] p-3.5 text-xs text-slate-400">
      <p className="text-sm font-medium text-slate-300">No measurement yet</p>
      <p className="mt-1">
        Transfer is sampled from the hypervisor every few minutes. Nothing has been recorded
        yet, so we&apos;re showing no usage figure rather than a zero we can&apos;t stand
        behind. Your plan allowance below is unchanged, and metering starts on its own —
        nothing for you to do.
      </p>
    </div>
  ) : (
    <div className="mb-4 space-y-1.5 text-xs">
      {bwPartial && (
        <p className="text-slate-400">
          <span className="font-medium text-slate-300">Partial period.</span> Metering has
          been running since {fmtBwDate(bwHealth.startedAt!)} and these totals only cover the
          time measured so far — read them as a floor, not as a full {BW_PERIOD_DAYS}-day
          total.
        </p>
      )}
      {!bwHealth.live && (
        <p className="text-amber-400">
          Metering last reported {fmtBwSpan(bwHealth.ageMs ?? 0)} ago, so these figures may be
          behind. Recent transfer is missing rather than counted.
        </p>
      )}
      {bwGap && bwHealth.gapAt && (
        <p className="text-amber-400">
          Metering was interrupted on {fmtBwDate(bwHealth.gapAt)} — transfer during that
          outage isn&apos;t included, so this period under-reports.
        </p>
      )}
    </div>
  )}

  {bandwidth.length === 0 ? (
    <p className="text-sm text-slate-400">No active servers.</p>
  ) : (
    <ul className="space-y-4">
      {bandwidth.map(({ server: s, view }) => {
        const pct = view.pct ?? 0;
        return (
          <li key={s.id}>
            <div className="mb-1.5 flex items-center justify-between gap-3 text-sm">
              <Link
                href={`/dashboard/servers/${s.id}`}
                className="min-w-0 flex-1 truncate font-medium hover:text-brand-300"
              >
                {s.hostname}
                <span className="ml-2 text-xs font-normal text-slate-500">{s.plan.name}</span>
              </Link>
              <span
                className={`shrink-0 font-mono text-xs ${
                  view.measured ? pctTone(pct) : "text-slate-500"
                }`}
              >
                {view.measured ? fmtBytes(view.usedBytes) : "—"} /{" "}
                {fmtBytes(view.allowanceBytes)}
              </span>
            </div>
            {view.measured ? (
              <MeterBar
                value={view.usedBytes}
                max={view.allowanceBytes}
                color={meterColor(pct)}
              />
            ) : (
              /* No bar at all: an empty meter reads as "you've used
                 nothing", which is a claim we cannot make. */
              <div className="h-2 w-full rounded-full border border-dashed border-white/[0.10]" />
            )}
            <p className="mt-1 text-xs text-slate-500">
              {view.measured && view.measuredFrom ? (
                <>
                  Measured since {fmtBwDate(view.measuredFrom)} ·{" "}
                  {view.partial
                    ? `${fmtBwSpan(view.coveredMs)} of ${BW_PERIOD_DAYS} days`
                    : `full ${BW_PERIOD_DAYS}-day period`}
                </>
              ) : (
                <>Awaiting the first sample</>
              )}
              {s.status !== "RUNNING" && <> · not accruing while {s.status.toLowerCase()}</>}
            </p>
            {view.measured && pct > 100 && (
              <p className="mt-1 text-xs text-red-400">
                Over allowance by {fmtBytes(view.usedBytes - view.allowanceBytes)} — overage
                may apply.
              </p>
            )}
            {view.measured && pct > 80 && pct <= 100 && (
              <p className="mt-1 text-xs text-amber-400">
                {pct.toFixed(0)}% of allowance used
                {view.partial ? ` in the ${fmtBwSpan(view.coveredMs)} measured so far` : ""} —
                approaching your plan limit.
              </p>
            )}
          </li>
        );
      })}
    </ul>
  )}
</div>

