// Pure-function sanity check for lib/bandwidth.ts. No DB access.
import {
  creditFromCounters,
  integrateRrdBytes,
  bwUsageView,
  BW_PERIOD_MS,
  type BwSample,
  type BwMeterHealth,
} from "/opt/nxeon/lib/bandwidth";

const t0 = Date.now();
const S = (o: Partial<BwSample>): BwSample => ({
  netin: 0,
  netout: 0,
  uptimeSec: 100_000,
  pid: 1000,
  atMs: t0,
  ...o,
});

const cases: Array<[string, BwSample, BwSample]> = [
  // clean 600s window, 1 GB out
  ["clean delta", S({ netin: 10e9, netout: 5e9 }), S({ netin: 11e9, netout: 6e9, atMs: t0 + 600_000, uptimeSec: 100_600 })],
  // VM restarted: pid changed, counters low
  ["reboot (pid change)", S({ netin: 10e9, netout: 5e9 }), S({ netin: 2e6, netout: 1e6, pid: 2000, uptimeSec: 120, atMs: t0 + 600_000 })],
  // VM restarted and already pushed MORE than the stale baseline ("hugely positive")
  ["reboot, counter now higher", S({ netin: 1e6, netout: 1e6 }), S({ netin: 40e9, netout: 40e9, pid: 2000, uptimeSec: 300, atMs: t0 + 600_000 })],
  // counters dropped but same process/uptime → ambiguous
  ["rollback, no restart", S({ netin: 10e9, netout: 5e9 }), S({ netin: 9e9, netout: 4e9, uptimeSec: 100_600, atMs: t0 + 600_000 })],
  // absurd delta
  ["implausible", S({ netin: 0, netout: 0 }), S({ netin: 5e15, netout: 5e15, uptimeSec: 100_600, atMs: t0 + 600_000 })],
  // soft reboot inside guest: process survives, counters keep climbing
  ["guest soft reboot", S({ netin: 10e9, netout: 5e9 }), S({ netin: 10.5e9, netout: 5.2e9, uptimeSec: 100_600, atMs: t0 + 600_000 })],
];
for (const [name, prev, cur] of cases) {
  const c = creditFromCounters(prev, cur);
  console.log(name.padEnd(26), c.reason.padEnd(18), "in", c.inBytes, "out", c.outBytes);
}

// RRD integration: 10 buckets of 60s at 1 MB/s out; window covers the last 5.
const nowSec = Math.floor(t0 / 1000);
const rows = Array.from({ length: 10 }, (_, i) => ({
  time: nowSec - (10 - i) * 60,
  netin: 2_000_000,
  netout: 1_000_000,
}));
console.log("rrd all:", integrateRrdBytes(rows, nowSec - 600, nowSec));
console.log("rrd last 5:", integrateRrdBytes(rows, nowSec - 300, nowSec));
console.log("rrd nulls:", integrateRrdBytes([{ time: nowSec - 120, netin: null, netout: null }], nowSec - 600, nowSec));
console.log("rrd empty:", integrateRrdBytes([], nowSec - 600, nowSec));

// UI view
const never: BwMeterHealth = { startedAt: null, lastAt: null, gapAt: null, backfillAt: null, live: false, ageMs: null };
const live: BwMeterHealth = {
  startedAt: new Date(t0 - 3 * 3600_000),
  lastAt: new Date(t0 - 60_000),
  gapAt: null,
  backfillAt: null,
  live: true,
  ageMs: 60_000,
};
const legacyRow = {
  status: "RUNNING",
  bwInBytes: 900n * 1_000_000_000n,
  bwOutBytes: 100n * 1_000_000_000n,
  bwWindowStart: new Date(t0 - 40 * 24 * 3600_000), // predates metering
};
console.log("never metered:", bwUsageView(legacyRow, 20e12, never, new Date(t0)));
console.log("live, partial:", bwUsageView(legacyRow, 20e12, live, new Date(t0)));
const fullRow = { ...legacyRow, bwWindowStart: new Date(t0 - BW_PERIOD_MS) };
const oldMeter: BwMeterHealth = { ...live, startedAt: new Date(t0 - 90 * 24 * 3600_000) };
console.log("live, full period partial flag:", bwUsageView(fullRow, 20e12, oldMeter, new Date(t0)).partial);

