136	/**
137	 * Last counter sample per `serverId:vmid`, in worker memory.
138	 *
139	 * Deliberately not persisted: prisma/schema.prisma has no column for a raw
140	 * per-VM counter, and the two obvious substitutes are worse than a cold start —
141	 * the `Setting` KV is handed wholesale to the admin settings page (it would ship
142	 * a blob of every server's counters to the browser), and reusing
143	 * `abuseBwMark` would break the abuse window it exists for. A worker restart
144	 * therefore loses the baseline; `backfillGap` recovers the interval from RRD so
145	 * the restart costs at most the newest (still-filling) RRD bucket instead of a
146	 * whole sweep interval.
147	 *
148	 * Keyed by vmid as well as serverId so a reinstall or migration onto a different
149	 * vmid can never be compared against the old VM's counters.
150	 */
151	const bwBaselines = new Map<string, BwSample>();
152	
153	/**
154	 * Sampling runs INLINE in the worker's strictly serial job loop: every second
155	 * spent here is a second no customer job runs, so the sweep is hard-bounded.
156	 * A Proxmox node that hangs must cost one timeout, not the queue.
157	 */
158	const BW_MAX_SERVERS_PER_SWEEP = 500;
159	const BW_CALL_TIMEOUT_MS = 8_000;
160	const BW_SWEEP_BUDGET_MS = 45_000;
161	/** RRD back-fill is ~10x the payload of a status read, so cap it per sweep. */
162	const BW_MAX_BACKFILLS_PER_SWEEP = 50;
163	/** Below this a gap is not worth an extra API call. */
164	const BW_BACKFILL_MIN_GAP_MS = 2 * 60_000;
165	/** `timeframe=hour` holds 60 x 60s buckets; beyond that the gap is unrecoverable. */
166	const BW_RRD_WINDOW_MS = 60 * 60_000;
167	
168	/**
169	 * Bound one Proxmox call. Note this abandons the promise rather than cancelling
170	 * the request (lib/proxmox takes no AbortSignal) — the point is that the sweep
171	 * moves on, not that the socket closes.
172	 */
173	function withTimeout<T>(p: Promise<T>, ms: number, what: string): Promise<T> {
174	  return new Promise<T>((resolve, reject) => {
175	    const timer = setTimeout(
176	      () => reject(new Error(`proxmox call timed out after ${ms}ms: ${what}`)),
177	      ms
178	    );
179	    p.then(
180	      (v) => {
181	        clearTimeout(timer);
182	        resolve(v);
183	      },
184	      (e) => {
185	        clearTimeout(timer);
186	        reject(e);
187	      }
188	    );
189	  });
190	}
191	
192	type BwClient = { get: (path: string, params?: Record<string, any>) => Promise<any> };
193	
194	/**
195	 * Meter every RUNNING VM's network counters onto its Server row.
196	 *
197	 * Writes `bwInBytes` / `bwOutBytes` (cumulative for the current metering period)
198	 * and `bwWindowStart` (the period marker). Nothing wrote these before, which is
199	 * why the customer's bandwidth panel read a permanent zero and worker/abuse.ts
200	 * could never fire — see lib/bandwidth.ts for the full history.
201	 *
202	 * READ-ONLY against Proxmox: `status/current` and `rrddata`, never a mutation.
203	 * Best-effort per server — one unreachable node must not cost the whole sweep.
204	 */
205	export async function sampleServerBandwidth(): Promise<void> {
