215	  }
216	  // End of the previous sweep — where a cold-start back-fill starts counting.
217	  // Only the cold path uses it; the warm path uses each baseline's own
218	  // timestamp, so a sweep cadence that drifts (or a sweep that gets skipped
219	  // entirely) stays correct without assuming a fixed interval.
220	  const priorSweepMs = health.lastAt?.getTime() ?? null;
221	
222	  let servers: Array<{
