239	        hostname: true,
240	        vmid: true,
241	        bwWindowStart: true,
242	        node: { select: { pveNode: true, apiUrl: true, tokenId: true, tokenSecret: true } },
243	      },
244	      take: BW_MAX_SERVERS_PER_SWEEP,
245	    });
246	  } catch (e) {
