248	    return;
249	  }
250	
251	  // On the very first sweep there is no stored start yet; treat now as the start
252	  // so window normalisation below has a truthful lower bound to work with.
253	  const startedAtMs = health.startedAt?.getTime() ?? sweepStartMs;
254	
255	  let sampled = 0;
256	  let backfills = 0;
257	  let backfilled = false;
258	  let gapDetected = false;
259	  const liveKeys = new Set<string>();
260	
261	  for (const s of servers) {
262	    if (s.vmid == null) continue;
263	    const key = `${s.id}:${s.vmid}`;
264	    liveKeys.add(key);
265	
