291	      // Our DB says RUNNING but Proxmox is authoritative. A stopped VM reports
292	      // netin/netout 0, and treating that as a counter rollback would be noise.
293	      if (String(cur?.status ?? "") !== "running") {
294	        bwBaselines.delete(key);
295	        continue;
296	      }
297	      const netin = Number(cur?.netin);
298	      const netout = Number(cur?.netout);
299	      if (!Number.isFinite(netin) || !Number.isFinite(netout)) {
300	        // Node too old / unexpected payload: no counters, nothing to meter.
301	        continue;
302	      }
303	      const sample: BwSample = {
304	        netin,
305	        netout,
306	        uptimeSec: Number(cur?.uptime) || 0,
307	        pid: Number.isFinite(Number(cur?.pid)) ? Number(cur.pid) : null,
308	        atMs: Date.now(),
309	      };
310	
311	      const prev = bwBaselines.get(key);
312	      bwBaselines.set(key, sample);
