// READ-ONLY dry run of the metering sweep's Proxmox path. Reads Server rows and
// GETs status/current + rrddata. Writes NOTHING (no DB writes, no PVE mutations).
import { db } from "/opt/nxeon/lib/db";
import { pve, node as defaultNode, pveFor } from "/opt/nxeon/lib/proxmox";
import { creditFromCounters, integrateRrdBytes, type BwSample } from "/opt/nxeon/lib/bandwidth";

const servers = await db.server.findMany({
  where: { status: "RUNNING", vmid: { not: null } },
  select: {
    id: true,
    hostname: true,
    vmid: true,
    bwWindowStart: true,
    node: { select: { pveNode: true, apiUrl: true, tokenId: true, tokenSecret: true } },
  },
  orderBy: { id: "asc" },
});
console.log(`servers: ${servers.length}`);

function clientFor(s: (typeof servers)[number]) {
  const c = s.node
    ? pveFor({ apiUrl: s.node.apiUrl, pveNode: s.node.pveNode, tokenId: s.node.tokenId, tokenSecret: s.node.tokenSecret })
    : pve;
  return { c, pnode: s.node?.pveNode ?? defaultNode, viaNodeRow: Boolean(s.node) };
}

const first = new Map<string, BwSample>();
for (const s of servers) {
  const { c, pnode, viaNodeRow } = clientFor(s);
  const cur = await c.get(`/nodes/${pnode}/qemu/${s.vmid}/status/current`);
  const sample: BwSample = {
    netin: Number(cur?.netin),
    netout: Number(cur?.netout),
    uptimeSec: Number(cur?.uptime) || 0,
    pid: Number.isFinite(Number(cur?.pid)) ? Number(cur.pid) : null,
    atMs: Date.now(),
  };
  first.set(s.id, sample);
  console.log(
    `${s.hostname}\tnode=${pnode} (nodeRow=${viaNodeRow}) status=${cur?.status} ` +
      `netin=${sample.netin} netout=${sample.netout} uptime=${sample.uptimeSec} pid=${sample.pid} ` +
      `windowStart=${s.bwWindowStart.toISOString()}`
  );
}

const waitMs = 25_000;
console.log(`\nwaiting ${waitMs / 1000}s for a second sample...\n`);
await new Promise((r) => setTimeout(r, waitMs));

for (const s of servers) {
  const { c, pnode } = clientFor(s);
  const cur = await c.get(`/nodes/${pnode}/qemu/${s.vmid}/status/current`);
  const sample: BwSample = {
    netin: Number(cur?.netin),
    netout: Number(cur?.netout),
    uptimeSec: Number(cur?.uptime) || 0,
    pid: Number.isFinite(Number(cur?.pid)) ? Number(cur.pid) : null,
    atMs: Date.now(),
  };
  const prev = first.get(s.id)!;
  const credit = creditFromCounters(prev, sample);
  const secs = (sample.atMs - prev.atMs) / 1000;
  console.log(
    `${s.hostname}\treason=${credit.reason} WOULD credit in=${credit.inBytes} out=${credit.outBytes} ` +
      `over ${secs.toFixed(1)}s → ${((credit.outBytes * 8) / secs / 1e6).toFixed(3)} Mbps out`
  );

  // RRD back-fill path over the last 10 minutes.
  const rows = await c.get(`/nodes/${pnode}/qemu/${s.vmid}/rrddata`, { timeframe: "hour", cf: "AVERAGE" });
  const nowSec = Math.floor(Date.now() / 1000);
  const filled = integrateRrdBytes(Array.isArray(rows) ? rows : [], nowSec - 600, nowSec);
  console.log(`  rrd backfill(last 10m): ${JSON.stringify(filled)}`);
}

await db.$disconnect();

